-- Adds the four new companies (Martenssons x2, My Driving Academy x2) with cost centers and a
-- chart of accounts built from Fortnox postings 2025-09-01 .. 2026-08-31 (P&L accounts 3000-8999
-- that had at least one posting in the window; 8999 "Arets resultat" excluded).
--
-- Source: Fortnox via Accountie (trans table), fetched 2026-10-20.
-- Cost centers: every code with a P&L posting in the window.
--
-- Idempotent: every INSERT is ON CONFLICT DO NOTHING, so it can be re-run safely.
-- DDL/DML only - verification lives in verify_companies_martenssons_mda.sql (separate snippet).
--
-- Decisions you may want to change before running:
--   * companies.fabric_key is left NULL - set it in Admin > Bolag once the Fabric mapping exists
--     (nb_push_dim_account.py COMPANY_MAP only knows bolag1..bolag4).
--   * cost_centers.region is left NULL. A cost center with NULL region is INVISIBLE to region
--     managers (NULL never matches) - fill it in Admin > Kostnadsstallen or with an UPDATE below.
--   * account_configs: section / is_intercompany / is_budgetable / display_order are copied from
--     the same account number in companies 1-4 (On Via TS, id 4, preferred). Accounts that exist
--     in none of them get section NULL and a default is_budgetable (3000-7799 except 3000, 3100,
--     3740; 78xx and 8xxx are not budgetable) - check the result with the verify file.

-- ---------------------------------------------------------------------------------------------
-- 1. Companies
-- ---------------------------------------------------------------------------------------------
INSERT INTO companies (name, org_number, fiscal_year_start)
VALUES
  ('Mårtenssons Trafikskola AB',               '556935-6370', 1),
  ('Mårtenssons Utbildningar AB',              '556643-0913', 1),
  ('My Driving Academy Sweden AB',             '556943-1587', 1),
  ('My Driving Academy Trafikskolor Sweden AB','559244-2734', 1)
ON CONFLICT (org_number) DO NOTHING;

-- ---------------------------------------------------------------------------------------------
-- 2. Cost centers  (format per row: code|name, rows separated by ;)
-- ---------------------------------------------------------------------------------------------
INSERT INTO cost_centers (company_id, code, name, is_active)
SELECT c.id,
       btrim(split_part(item, '|', 1)),
       btrim(split_part(item, '|', 2)),
       NOT (raw.org = '556935-6370' AND btrim(split_part(item, '|', 1)) = '309')  -- 309 is inactive in Fortnox
FROM (VALUES
